import subprocess, pathlib, hashlib, json, datetime
r=pathlib.Path.cwd()
def git(*a):
 p=subprocess.run(['git','--no-optional-locks',*a],capture_output=True,check=True); return p.stdout
status=git('status','--porcelain=v1','-z','--untracked-files=all')
paths=set(x.decode('utf-8') for x in git('ls-files','-z','--cached','--others','--exclude-standard').split(b'\0') if x)
files={}
for p in sorted(paths):
 q=r/p
 if q.is_file():
  h=hashlib.sha256()
  with q.open('rb') as f:
   for b in iter(lambda:f.read(1048576),b''): h.update(b)
  files[p]={'sha256':h.hexdigest(),'bytes':q.stat().st_size}
 elif not q.exists(): files[p]={'absent':True}
 else: raise RuntimeError('Unexpected non-file path: '+p)
out={'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':files,'status_hex':status.hex(),'index_sha256':hashlib.sha256((r/'.git/index').read_bytes()).hexdigest(),'index_entries_sha256':hashlib.sha256(git('ls-files','--stage','-z')).hexdigest(),'cached_diff_sha256':hashlib.sha256(git('diff','--cached','--binary','--no-ext-diff')).hexdigest(),'unstaged_diff_sha256':hashlib.sha256(git('diff','--binary','--no-ext-diff')).hexdigest(),'head':git('rev-parse','HEAD').decode().strip(),'origin_ref':git('rev-parse','refs/remotes/origin/thesis-v7').decode().strip(),'status_count':len([x for x in status.split(b'\0') if x]),'tracked_changes':[x.decode('utf-8') for x in status.split(b'\0') if x and not x.startswith(b'??')]}
out['files_digest']=hashlib.sha256(json.dumps(files,sort_keys=True,separators=(',',':')).encode()).hexdigest()
out['file_count']=len(files)
out['total_bytes']=sum(x.get('bytes',0) for x in files.values())
out['status_sha256']=hashlib.sha256(status).hexdigest()
out.pop('status_hex')
out.pop('files')
print(json.dumps(out,ensure_ascii=True))
print(json.dumps({'git_config_sha256':hashlib.sha256((r/'.git/config').read_bytes()).hexdigest(),'head_file_sha256':hashlib.sha256((r/'.git/HEAD').read_bytes()).hexdigest()}))
